namespace HexMapEditor.Tests
{
    internal static class Groups041Tests
    {
        const BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;
        static string root;
        static object Get(MainWindow w,string n){return typeof(MainWindow).GetField(n,F).GetValue(w);}
        static void Set(MainWindow w,string n,object v){typeof(MainWindow).GetField(n,F).SetValue(w,v);}
        static object Call(MainWindow w,string n,params object[] args){return typeof(MainWindow).GetMethods(F).Single(m=>m.Name==n&&m.GetParameters().Length==args.Length).Invoke(w,args);}
        static MapData Map(MainWindow w){return (MapData)Get(w,"map");}
        static int Count(MainWindow w,string n){return ((ICollection)Get(w,n)).Count;}
        static HashSet<string> Selected(MainWindow w){return (HashSet<string>)Get(w,"selectedObjects");}
        static string Snapshot(MainWindow w){return MapLogic.Serializer().Serialize(Map(w));}
        static void Check(bool b,string why){if(!b)throw new Exception(why);}
        static void Undo(MainWindow w,bool redo=false){object[] a={redo,null};Check((bool)Call(w,"TryHistory",a),"History: "+a[1]);}
        static MapData Grid(){var map=new MapData{Columns=8,Rows=5};for(int i=0;i<40;i++)map.Cells.Add(new CellData());return map;}
        static ObjectTemplate Setup(MainWindow w){Set(w,"map",Grid());Call(w,"PositionOverlays");Set(w,"pan",new PointF(150,120));Set(w,"scale",1f);var t=new ObjectTemplate{Name="Przeciwnik",Asset=IconAssets.Starters()[1]};((List<ObjectTemplate>)Get(w,"libraryObjects")).Add(t);Call(w,"SelectObjectTemplate",t.Id);Call(w,"CaptureSavedState");return t;}
        static MapObject Place(MainWindow w,int col,int row){return (MapObject)Call(w,"PlaceObject",BrushGeometry.Center(Map(w),col,row));}
        static Point Screen(MainWindow w,PointF p){var pan=(PointF)Get(w,"pan");float scale=(float)Get(w,"scale");return new Point((int)Math.Round(pan.X+p.X*scale),(int)Math.Round(pan.Y+p.Y*scale));}
        static MouseEventArgs Mouse(Point p){return new MouseEventArgs(MouseButtons.Left,1,p.X,p.Y,0);}
        static void SelectBoth(MainWindow w){Selected(w).Clear();Selected(w).UnionWith(Map(w).Objects.Select(o=>o.Id));Set(w,"selectedGroupId",null);}
        static void Model()
        {
            using(var w=new MainWindow()){
                Setup(w);var a=Place(w,1,1);var b=Place(w,2,1);Check(a.Size==30&&b.Size==30,"Default size");a.Name="Goblin";b.Name="Ork";a.Side="Ally";a.RevealsFog=true;a.Locked=true;a.Size=25;b.Size=45;string baseData=MapLogic.Serializer().Serialize(Map(w).Objects);SelectBoth(w);Check((bool)Call(w,"CreateObjectGroup","Drużyna"),"Create group");var group=Map(w).Groups.Single();string gid=group.Id;Check(group.StateId==null&&!group.Locked.HasValue&&group.SizeMode=="Individual"&&MapLogic.Serializer().Serialize(Map(w).Objects)==baseData,"Initial group changes bases");
                Call(w,"ChooseObjectMember",Map(w).Objects[0],false,true);Check(Selected(w).SetEquals(new[]{a.Id})&&Get(w,"selectedGroupId")==null,"Alt before group selection");Call(w,"ChooseObjectMember",Map(w).Objects[1],false,false);Check(Selected(w).Count==2&&(string)Get(w,"selectedGroupId")==gid,"Click group");Call(w,"ChooseObjectMember",Map(w).Objects[1],true,false);Check(Selected(w).Count==0,"Ctrl remove group");Call(w,"ChooseObjectMember",Map(w).Objects[0],true,false);Check(Selected(w).Count==2,"Ctrl add group");
                string blocked=(string)Call(w,"AddObjectState","Skamieniały","#777777",false),allowed=(string)Call(w,"AddObjectState","Przewodnik","#DEB53B",true);Check(Map(w).Objects[0].Side=="Ally","Adding state selected it");group=Map(w).Groups.Single().Copy();group.StateId=blocked;group.RevealsFog=true;group.Locked=false;group.SizeMode="Offset";group.SizeValue=10;Call(w,"ChangeObjectGroup",group,null);var effective=GroupRules.Effective(Map(w),Map(w).Objects[0]);Check(!effective.RevealsFog&&!effective.Locked&&effective.Size==35&&Map(w).Objects[0].RevealsFog&&Map(w).Objects[0].Locked&&Map(w).Objects[0].Size==25,"Non-destructive overlay");
                var member=Map(w).Objects[0].Copy();member.Name="Ogr";member.Size=40;Call(w,"ChangeObject",member);Check(GroupRules.Effective(Map(w),Map(w).Objects[0]).Size==50&&Map(w).Groups.Single().SizeValue==10,"Alt base edit/offset accumulation");group=Map(w).Groups.Single().Copy();group.StateId=allowed;group.SizeMode="Common";group.SizeValue=60;group.RevealRadius=2;Call(w,"ChangeObjectGroup",group,null);Check(Map(w).Objects.All(o=>GroupRules.Effective(Map(w),o).Size==60)&&Map(w).Objects[0].Size==40,"Common size destroys bases");
                var before=Snapshot(w);int count=Count(w,"undo");Check(!(bool)Call(w,"DetachObjects",gid,new[]{a.Id},null)&&Snapshot(w)==before&&Count(w,"undo")==count,"Cancelled detach");
                foreach(var keep in new[]{new bool[5],Enumerable.Repeat(true,5).ToArray(),new[]{true,false,true,false,true}}){var old=Map(w).Objects[0].Copy();var result=GroupRules.Effective(Map(w),old);Call(w,"DetachObjects",gid,new[]{old.Id},keep);var now=Map(w).Objects.Single(o=>o.Id==old.Id);Check(now.X==old.X&&now.Y==old.Y&&now.Name==old.Name&&now.Size==(keep[1]?result.Size:old.Size)&&now.Side==(keep[0]?result.Side:old.Side)&&now.Locked==(keep[2]?result.Locked:old.Locked),"Detach categories/positions");Check(Map(w).Groups.Single().Members.Count==1,"Single-member group lost");Undo(w);Check(Snapshot(w)==before,"Detach Undo snapshot");Undo(w,true);Undo(w);}
                Call(w,"DetachObjects",gid,Map(w).Groups.Single().Members.ToArray(),new bool[5]);Check(Map(w).Groups.Count==0&&Map(w).Objects[0].Size==40,"Dissolve restore");Undo(w);Call(w,"DetachObjects",gid,Map(w).Groups.Single().Members.ToArray(),Enumerable.Repeat(true,5).ToArray());Check(Map(w).Groups.Count==0&&Map(w).Objects.All(o=>o.Size==60&&o.Side==allowed),"Dissolve keep");Undo(w);
                Selected(w).Clear();Selected(w).Add(a.Id);Call(w,"DeleteSelectedObjects");Check(Map(w).Groups.Single().Members.Count==1,"Delete member dangling ref");Selected(w).Clear();Selected(w).Add(b.Id);Call(w,"DeleteSelectedObjects");Check(Map(w).Groups.Count==0,"Empty group not removed");Undo(w);Undo(w);Check(Map(w).Groups.Single().Members.Count==2,"Deletion Undo group");
                string path=Path.Combine(root,"portable.hexmap");object[] save={path,false,null};Check((bool)Call(w,"TrySaveTo",save),"Save model: "+save[2]);var saved=MapLogic.Serializer().Deserialize<MapData>(File.ReadAllText(path));Check(saved.FormatVersion==5&&saved.Groups.Count==1&&saved.ObjectStates.Count==5&&saved.IconAssets.Count==1,"Portable format 5");((List<ObjectTemplate>)Get(w,"libraryObjects")).Clear();object[] open={path,null,false};Check((bool)Call(w,"TryLoadProject",open)&&Map(w).Groups.Single().Id==gid&&Map(w).Objects[0].Size==40,"Portable load bases/group");
                string stable=Snapshot(w);saved.Groups[0].Members.Add(saved.Groups[0].Members[0]);File.WriteAllText(path,MapLogic.Serializer().Serialize(saved));open=new object[]{path,null,false};Check(!(bool)Call(w,"TryLoadProject",open)&&Snapshot(w)==stable,"Invalid member changed document");Call(w,"CaptureSavedState");
            }
        }
        static void Fog()
        {
            using(var w=new MainWindow()){
                Setup(w);Place(w,1,1);Place(w,2,1);SelectBoth(w);Call(w,"CreateObjectGroup","Odkrywcy");string allowed=(string)Call(w,"AddObjectState","Własny odkrywca","#407040",true);var group=Map(w).Groups.Single().Copy();group.StateId=allowed;group.RevealsFog=true;group.RevealRadius=1;Map(w).Cells.ForEach(c=>c.Fog=true);Map(w).Cells[0].Fog=false;int count=Count(w,"undo");Call(w,"ChangeObjectGroup",group,null);Check(Count(w,"undo")==count+1&&!Map(w).Cells[0].Fog&&Map(w).Cells.Count(c=>!c.Fog)>2,"Custom state group reveal");Undo(w);Check(!Map(w).Cells[0].Fog&&Map(w).Cells.Count(c=>!c.Fog)==1,"Settings Undo old fog");Undo(w,true);
                Map(w).Cells.ForEach(c=>c.Fog=false);count=Count(w,"undo");Call(w,"SelectTool",EditorTool.FogBucket);Call(w,"BeginMaterialStroke",0,EditorTool.FogBucket);Call(w,"VisitBucketRegion",0);Check(!Map(w).Cells[1*8+1].Fog,"Discoverer disappeared during bucket");Call(w,"FinishStroke");Check(Count(w,"undo")==count+1&&Map(w).Cells.Any(c=>c.Fog),"Manual fog one final transaction");Undo(w);Check(Map(w).Cells.All(c=>!c.Fog),"Manual fog Undo");Undo(w,true);
                var beforeFog=Map(w).Cells.Select(c=>c.Fog).ToArray();Selected(w).Clear();Set(w,"selectedGroupId",null);Set(w,"selected",0);Set(w,"rightPanelOpen",true);Call(w,"UpdateUI");Call(w,"SelectTool",EditorTool.Hand);var obj=Map(w).Objects[0];Point start=Screen(w,new PointF(obj.X,obj.Y)),end=Screen(w,BrushGeometry.Center(Map(w),5,1));count=Count(w,"undo");Call(w,"CanvasMouseDown",null,Mouse(start));Check((int)Get(w,"selected")==0&&(bool)Get(w,"rightPanelOpen"),"Hand rebuilt/closed hex panel");Call(w,"CanvasMouseMove",null,Mouse(end));Call(w,"CanvasMouseUp",null,Mouse(end));Check(Count(w,"undo")==count+1&&Math.Abs((Map(w).Objects[1].X-Map(w).Objects[0].X)-48.49742f)<.001,"Hand group move");Undo(w);Check(Map(w).Cells.Select(c=>c.Fog).SequenceEqual(beforeFog),"Movement Undo changed earlier discovery");Undo(w,true);
                string state=Snapshot(w);count=Count(w,"undo");bool dirty=(bool)Get(w,"dirty");Call(w,"SetFogPreview",true);Check(Snapshot(w)==state&&Count(w,"undo")==count&&(bool)Get(w,"dirty")==dirty,"View changes data/history/dirty");Call(w,"ResolvePreviewFogRequest",false);Check((bool)Get(w,"previewWithoutFog")&&Snapshot(w)==state,"Preview refusal changed state");
                var o=Map(w).Objects[0];o.X=0;o.Y=0;o.Size=100;Map(w).Cells.ForEach(c=>c.Fog=true);Call(w,"SetFogPreview",false);var item=(ListViewItem)Call(w,"ObjectListItem",o);Check(item.Text=="???"&&item.SubItems[1].Text=="???"&&item.ImageKey=="hidden"&&item.SubItems[4].Text.StartsWith("Częściowo ukryty"),"Partial list mask");o.Size=8;Check(((ListViewItem)Call(w,"ObjectListItem",o)).SubItems[4].Text=="Ukryty","Full mask");o.X=-150;Check(((ListViewItem)Call(w,"ObjectListItem",o)).SubItems[3].Text=="Poza mapą","Outside mask");o.X=0;Call(w,"SetFogPreview",true);item=(ListViewItem)Call(w,"ObjectListItem",o);Check(item.Text==o.Name&&item.SubItems[1].Text=="Własny odkrywca"&&item.SubItems[4].Text=="Ukryty","Preview actual list/effective state");
                string path=Path.Combine(root,"preview.hexmap");object[] save={path,false,null};Check((bool)Call(w,"TrySaveTo",save),"Save preview");Check(MapLogic.Serializer().Deserialize<MapData>(File.ReadAllText(path)).Cells.All(c=>c.Fog),"Preview erased saved fog");object[] open={path,null,false};Check((bool)Call(w,"TryLoadProject",open)&&!(bool)Get(w,"previewWithoutFog")&&Map(w).Cells.All(c=>c.Fog),"Load preview reset/re-reveal");Call(w,"SetFogPreview",true);Call(w,"ResolvePreviewFogRequest",true);Check(!(bool)Get(w,"previewWithoutFog")&&Map(w).Cells.All(c=>c.Fog),"Preview agreement paints same gesture");Call(w,"CaptureSavedState");
            }
        }
        static void Controls()
        {
            using(var w=new MainWindow()){
                var template=Setup(w);var obj=Place(w,2,2);Call(w,"ChooseObjectMember",obj,false,true);Call(w,"CaptureSavedState");var name=(TextBox)Get(w,"objectName");int count=Count(w,"undo");name.Text="G";name.Text="Go";name.Text="Goblin";Check(Count(w,"undo")==count+1&&Map(w).Objects[0].Name=="Goblin"&&(bool)Get(w,"dirty"),"Name each letter undo");Call(w,"EndObjectPropertyEdit");Undo(w);Check(Map(w).Objects[0].Name=="Przeciwnik"&&!(bool)Get(w,"dirty"),"Name session Undo");Undo(w,true);name.Text="";Check(Map(w).Objects[0].Name=="Goblin","Empty name entered model");Call(w,"EndObjectPropertyEdit");Call(w,"UpdateUI");
                var size=(ScrubNumber)Get(w,"objectSize");count=Count(w,"undo");size.BeginText();size.Text="31";size.Text="35";size.Text="42";size.CommitText();Check(Count(w,"undo")==count+1&&Map(w).Objects[0].Size==42,"Numeric session split");Call(w,"EndObjectPropertyEdit");Undo(w);Check(Map(w).Objects[0].Size==30,"Numeric Undo");Undo(w,true);
                count=Count(w,"undo");((CheckBox)Get(w,"objectLocked")).Checked=true;Check(Count(w,"undo")==count+1&&Map(w).Objects[0].Locked,"Checkbox transaction");
                Call(w,"FitMap");var pan=(PointF)Get(w,"pan");float scale=(float)Get(w,"scale");Call(w,"FitEverything");Check((PointF)Get(w,"pan")==pan&&(float)Get(w,"scale")==scale,"Contained object fit differs");var second=Place(w,3,2);SelectBoth(w);Call(w,"CreateObjectGroup","Duże");var group=Map(w).Groups.Single().Copy();group.SizeMode="Common";group.SizeValue=1000;Call(w,"ChangeObjectGroup",group,null);Call(w,"FitEverything");Check((float)Get(w,"scale")<scale,"Effective bounds ignored");
                Call(w,"SelectTool",EditorTool.Select);Point empty=new Point(5,5);Selected(w).Clear();Set(w,"selectedGroupId",null);Set(w,"selected",0);Set(w,"rightPanelOpen",true);Call(w,"CanvasMouseDown",null,Mouse(empty));Call(w,"CanvasMouseUp",null,Mouse(empty));Check((int)Get(w,"selected")==-1&&!(bool)Get(w,"rightPanelOpen"),"Empty outside click keeps hex panel");
                var buttons=(Dictionary<EditorTool,Button>)Get(w,"toolButtons");Check(buttons.ContainsKey(EditorTool.RectangleSelect)&&buttons.ContainsKey(EditorTool.Lasso)&&buttons.Count==8,"Separate visible selection tools");
                // File operation is represented once; name semantics change only for object instances.
                string dir=Path.Combine(root,"Objects");((List<ObjectTemplate>)Get(w,"libraryObjects")).Clear();var own=new ObjectTemplate{Name="Przeciwnik",Asset=template.Asset};object[] change={null,own,false,dir,null};Check((bool)Call(w,"TryChangeObjectTemplate",change),"Own template");var stored=((List<ObjectTemplate>)Get(w,"libraryObjects")).Single();foreach(var o in Map(w).Objects)o.TemplateId=stored.Id;var replacement=stored.Copy();replacement.Name="Wróg";replacement.Asset=IconAssets.Starters()[2];change=new object[]{stored,replacement,true,dir,null};string[] names=Map(w).Objects.Select(o=>o.Name).ToArray();Check((bool)Call(w,"TryChangeObjectTemplate",change)&&Map(w).Objects.Select(o=>o.Name).SequenceEqual(names)&&Map(w).Objects.All(o=>o.AssetId==replacement.Asset.Id),"Template overwrote instance names");Undo(w);Check(Map(w).Objects.Select(o=>o.Name).SequenceEqual(names),"Template Undo names");
                Call(w,"SelectObjectTemplate",stored.Id);Check(((Button)Get(w,"deleteObjectButton")).Enabled,"Trash selected template disabled");Call(w,"ClearIconMaterial");Check(!((Button)Get(w,"deleteObjectButton")).Enabled,"Trash enabled without template");Call(w,"CaptureSavedState");
            }
        }
        static void Fixture(string path)
        {
            string warning;var templates=ObjectLibrary.Load(Path.Combine(path,"Library","Objects"),out warning);var map=Grid();var t=templates[0];map.IconAssets.Add(t.Asset);for(int i=0;i<map.Cells.Count;i++)map.Cells[i].Fog=i%map.Columns>=4;
            for(int i=0;i<2;i++){var p=BrushGeometry.Center(map,i+1,1);map.Objects.Add(new MapObject{TemplateId=t.Id,Name=i==0?"Goblin":"Ork",AssetId=t.Asset.Id,X=p.X,Y=p.Y});}File.WriteAllText(Path.Combine(path,"Próba grup.hexmap"),MapLogic.Serializer().Serialize(map));
        }
        [STAThread]static int Main(string[] args){Application.EnableVisualStyles();Application.SetCompatibleTextRenderingDefault(false);root=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"data");Directory.CreateDirectory(root);try{if(args.Length==2&&args[0]=="fixture"){Fixture(args[1]);return 0;}if(args.Length!=1)throw new Exception("Choose model, fog or controls");switch(args[0]){case "model":Model();break;case "fog":Fog();break;case "controls":Controls();break;default:throw new Exception("Unknown case");}Console.WriteLine("PASS "+args[0]+"; targeted 0.4.1 scenario only.");return 0;}catch(Exception ex){Console.Error.WriteLine(ex);return 1;}}
    }
}
